 function offerDescription(o){const r=snapshot.reservations.find(r=>r.id===o.fromReservationId),other=snapshot.reservations.find(r=>r.id===o.toReservationId);return (r?dateLabel(r.date)+' · '+slotName(r.spaceId)+' · '+r.start+' – '+r.end:'Pôvodná rezervácia už nie je dostupná')+(other?' ↔ '+dateLabel(other.date)+' · '+slotName(other.spaceId):'');}
 function actionableOffer(o){if(!snapshot||o.status!=='pending'||o.expiresAt&&Date.parse(o.expiresAt)<=Date.now())return false;const r=snapshot.reservations.find(r=>r.id===o.fromReservationId);if(!r||fleetCar(r)||!eligible(r.date))return false;if(o.type==='swap'){const other=snapshot.reservations.find(r=>r.id===o.toReservationId);if(!other||fleetCar(other)||!eligible(other.date))return false;}return true;}
