 function renderProfile(){const v=vehicle(snapshot.me.id),supported='Notification' in global,granted=supported&&Notification.permission==='granted';return '<section class="garage-card"><h2>Moje auto</h2><div class="garage-profile-preview"><span class="garage-car">'+carSvg(v)+'</span><div><h3>'+esc(snapshot.me.name)+'</h3><p>'+esc(v.brand||'Nastavte model a farbu svojho auta')+'</p></div></div><form id="garage-profile-form"><div class="garage-fields two">'+modelPicker('garage-vehicle-brand',v.brand)+'<label>Farba auta<input type="color" id="garage-vehicle-color" value="'+esc(v.color)+'"></label></div><p class="garage-muted">Váš model a farba pomôžu kolegom spoznať obsadené miesto.</p><button type="submit" class="garage-button">Uložiť moje auto</button></form></section><section class="garage-card"><h2>Upozornenia</h2><p>'+(!supported?'Tento prehliadač nepodporuje upozornenia. Na iPhone otvorte Satori ako aplikáciu pridanú na plochu.':granted?'Upozornenia sú povolené. Prihláste tento telefón na upozornenia Garáže.':'Zapnite upozornenia na uvoľnené miesta a ponuky od kolegov.')+'</p>'+(supported&&options.registerPush?'<button type="button" class="garage-button secondary" data-garage-action="notifications">'+(granted?'Aktivovať upozornenia Garáže':'Zapnúť upozornenia')+'</button>':'')+'</section>';}
