 function openFleetCar(id){if(!snapshot.me.canAdmin)return;const r=id?snapshot.reservations.find(r=>r.id===id&&mine(r)&&fleetCar(r)):null;if(id&&!r)return;const slots=snapshot.config.slots.filter(canUse).sort((a,b)=>a.floor-b.floor||a.order-b.order),pooled=r&&slotById(r.spaceId)&&slotById(r.spaceId).floor===-1,choices=slots.filter(s=>s.floor!==-1).map(s=>'<option value="'+esc(s.id)+'" '+(r&&r.spaceId===s.id?'selected':'')+'>'+esc(slotName(s.id))+'</option>').join('')+(slots.some(s=>s.floor===-1)?'<option value="pool:-1" '+(pooled?'selected':'')+'>Parkovanie · −1. poschodie</option>':'');
  showDialog(r?'Upraviť ďalšie auto':'Rezervovať ďalšie auto','<form id="garage-fleet-form"><p class="garage-muted">Miesto rezervujete pre uvedené auto. Váš deň v kancelárii sa tým nemení.</p><div class="garage-fields"><label>Čie auto?<input id="garage-fleet-name" type="text" maxlength="120" value="'+esc(r?r.name:'')+'" placeholder="Meno kolegu alebo účel odovzdania" required></label><label>Model auta<input id="garage-fleet-brand" type="text" maxlength="60" list="garage-fleet-models" value="'+esc(r?bookingVehicle(r).brand:'')+'" placeholder="Vyberte alebo napíšte model" required><datalist id="garage-fleet-models">'+FLEET_MODELS.map(m=>'<option value="'+esc(m.label)+'"></option>').join('')+'</datalist></label><label>Farba auta<input id="garage-fleet-color" type="color" value="'+esc(r?bookingVehicle(r).color:'#ffffff')+'"></label><label>Dátum<input id="garage-fleet-date" type="date" value="'+esc(r?r.date:eligible(selectedDate)?selectedDate:snapshot.window.start)+'" min="'+snapshot.window.start+'" max="'+snapshot.window.end+'" required></label><label>Miesto<select id="garage-fleet-space">'+choices+'</select></label></div>'+intervalMarkup('garage-fleet',r?r.start:start,r?r.end:end)+'<button type="submit" class="garage-button">'+(r?'Uložiť zmenu':'Rezervovať pre toto auto')+'</button></form>'+(r?'<button type="button" class="garage-button danger secondary" data-garage-cancel="'+esc(r.id)+'">Zrušiť rezerváciu auta</button>':''),()=>{const t=formInterval('garage-fleet'),d=val('garage-fleet-date'),space=val('garage-fleet-space'),name=val('garage-fleet-name').trim(),brand=val('garage-fleet-brand').trim();if(!name||!brand){dialogError('Vyplňte, čie auto parkuje, a jeho model.');return;}if(!eligible(d)){dialogError('Vyberte dátum v najbližších 30 dňoch.');return;}if(t)mutate('reservationSave',Object.assign({kind:'fleet',name,vehicle:{brand,color:val('garage-fleet-color')},date:d},space==='pool:-1'?{floor:-1}:{spaceId:space},t,r?{id:r.id,revision:r.revision}:{}),'Parkovanie pre uvedené auto bolo potvrdené.');});
 }
 async function loadUsers(force){if(!usable()||!snapshot.me.canAdmin)return;if(usersPromise&&!force)return usersPromise;const who=owner,gen=epoch,request=++usersGeneration;usersLoading=true;usersError='';if(view==='admin')render(true);const promise=(async()=>{try{if(typeof options.loadUsers!=='function')throw new Error('Zoznam používateľov ešte nie je dostupný. Obnovte aplikáciu.');const data=await options.loadUsers(!!force);if(!same(who,gen)||request!==usersGeneration)return;if(!data||data.ok!==true||!Array.isArray(data.users))throw new Error(data&&data.error||'Používateľov sa nepodarilo načítať.');users=data.users.map(u=>fields(u,['id','name','sourceLine','sourceRole','role','weeklyDays','access','sourceConflict','sourceMissing','boundSourceLine','officeDaysError']));}catch(e){if(same(who,gen)&&request===usersGeneration)usersError=friendly(e);}finally{if(same(who,gen)&&request===usersGeneration){usersLoading=false;usersPromise=null;if(view==='admin')render(true);}}})();usersPromise=promise;return promise;}
 function renderUsers(){return '<section class="garage-card"><div class="garage-section-head"><h2>Používatelia a prístup</h2><button type="button" class="garage-button secondary" data-garage-action="users-refresh">Obnoviť zoznam</button></div><p class="garage-muted">Účty, roly a počet dní v kancelárii upravujete v Google Sheets, v hárku Pouzivatelia. Tu zapínate prístup do Garáže.</p>'+(usersLoading?'<p class="garage-status-loading">Načítavam používateľov…</p>':'')+(usersError?'<p class="garage-dialog-error" role="alert">'+esc(usersError)+'</p>':'')+'<label class="garage-fields">Hľadať používateľa<input id="garage-user-search" type="search" placeholder="Meno alebo login"></label><div id="garage-users-list"></div></section>';}
 function renderUsersList(query){if(!root)return;const list=root.querySelector('#garage-users-list');if(!list)return;const q=normal(query),labels={gp:'Golem',gyn:'Gynekológia',reagila:'Reagila'},rows=users.filter(u=>normal(u.name+' '+u.id+' '+(labels[u.sourceLine]||'')).includes(q));list.innerHTML=rows.map((u,index)=>{const detailId='garage-retained-'+(u.sourceLine+':'+u.id).replace(/[^a-z0-9]/gi,c=>'_'+c.codePointAt(0).toString(16)+'_');const retained=u.access===false?snapshot.reservations.filter(r=>r.owner===u.id):[];const locked=u.id===snapshot.me.id||u.sourceConflict===true||u.sourceMissing===true;return '<article class="garage-user-row"><div><strong>'+esc(u.name||u.id)+'</strong><small>'+esc(u.id)+' · '+esc(labels[u.sourceLine]||u.sourceLine)+' · '+esc(u.sourceRole||u.role)+'</small><small>'+esc(Number(u.weeklyDays)||0)+' dní v kancelárii / týždeň</small>'+(u.officeDaysError?'<small class="garage-waiting">'+esc(u.officeDaysError)+'</small>':'')+(u.sourceMissing?'<small>Účet už nie je v zdrojovom hárku. Rezervácie môžete uvoľniť.</small>':'')+(u.sourceConflict?'<small>Účet je viazaný na '+esc(labels[u.boundSourceLine]||u.boundSourceLine)+'.</small>':'')+(retained.length&&!u.sourceConflict?'<details id="'+detailId+'" class="garage-details"><summary>Zostávajúce rezervácie ('+retained.length+')</summary>'+retained.map(r=>'<p>'+esc(dateLabel(r.date))+' · '+esc(slotName(r.spaceId))+' · '+esc(r.start)+' – '+esc(r.end)+'</p><button type="button" class="garage-button danger secondary" data-garage-cancel="'+esc(r.id)+'">Uvoľniť rezervované miesto</button>').join('')+'</details>':'')+'</div><label class="garage-access-control"><input type="checkbox" role="switch" aria-label="Prístup do Garáže pre '+esc(u.name||u.id)+' z '+esc(labels[u.sourceLine]||u.sourceLine)+'" data-garage-access="'+esc(u.id)+'" data-source="'+esc(u.sourceLine)+'" data-locked="'+locked+'" '+(u.access?'checked ':'')+(busy||usersLoading||locked?'disabled':'')+'><span>Prístup do Garáže</span></label></article>';}).join('')+(!rows.length&&!usersLoading?'<p class="garage-muted">'+(q?'Nenašli sa zodpovedajúci používatelia.':'Zoznam sa načíta po overení zdrojových účtov.')+'</p>':'');}
